package com.studenttong.mobile;
import android.Manifest;import android.app.*;import android.content.*;import android.location.*;import android.os.*;import android.text.Html;import android.webkit.CookieManager;import android.widget.*;import org.json.*;import java.util.*;import java.io.*;import javax.net.ssl.HttpsURLConnection;
/** Account-scoped attendance. Location preparation never means attendance success. */
public final class SigninUi {
 final MainActivity a;JSONObject course,current;Location point;LocationManager manager;LocationListener listener;Runnable timeout;boolean pollBusy;long submittedAt;String reminded="";
 SigninUi(MainActivity a){this.a=a;try{course=new JSONObject(a.store.setting(a.aid,"signinCourse","{}"));current=new JSONObject(a.store.setting(a.aid,"signinCurrent","{}"));}catch(Exception ignored){course=new JSONObject();current=new JSONObject();}}
 JSONObject record(String id){try{return new JSONObject(a.store.setting(a.aid,"signin:"+id,"{}"));}catch(Exception e){return new JSONObject();}}
 void state(String phase,String message){try{if(current==null||!current.has("id"))return;JSONObject r=record(current.getString("id"));r.put("state",phase).put("message",message).put("time",System.currentTimeMillis());a.store.setSetting(a.aid,"signin:"+current.getString("id"),r.toString());a.message(message);}catch(Exception ignored){}}
 static String label(String s){return s.equals("completed")?"已签到":s.equals("submitting")?"等待平台回执":s.equals("located")?"已定位，待确认":s.equals("verification")?"需要人工验证":s.equals("rejected")?"平台未接受":s.equals("uncertain")?"结果待核对":s.equals("ended")?"已结束":"待处理";}
 void show(){LinearLayout p=a.scroller();p.addView(a.text("签到",24));if(a.account==null){p.addView(a.button("选择账号",()->a.chooseAccount()));return;}LinearLayout mode=a.card(p);mode.addView(Ui.badge(a,LocationModeManager.label(a,a.aid)));try{JSONObject fix=new JSONObject(a.store.setting(a.aid,"location.lastSystem","{}"));if(fix.has("latitude")){mode.addView(a.text(String.format(Locale.ROOT,"纬度 %.6f　经度 %.6f · WGS-84",fix.optDouble("latitude"),fix.optDouble("longitude")),13));mode.addView(a.text("来源："+(fix.optBoolean("isMock")?"系统模拟定位":fix.optString("provider").equals("gps")?"GPS 真实定位":"网络定位")+" · 精度 "+fix.optDouble("accuracy")+" 米\n时间："+new java.text.SimpleDateFormat("MM-dd HH:mm:ss",Locale.CHINA).format(new Date(fix.optLong("time")))+" · Mock "+(fix.optBoolean("isMock")?"是":"否"),12));}else mode.addView(a.text("暂无定位 · 未向平台提交",13));}catch(Exception ignored){}LinearLayout links=a.row();a.equal(links,a.button("地图选点",()->LocationMapActivity.open(a,a.aid,false)));a.equal(links,a.button("定位诊断",()->LocationMapActivity.open(a,a.aid,true)));mode.addView(links);if(!"chaoxing".equals(a.platform)){p.addView(a.text("雨课堂签到请在平台页面处理。",14));return;}if(a.slotIndex()<0){Button open=a.button("打开当前账号签到中心",()->{try{a.openAccount(a.account);}catch(Exception e){a.message(e.getMessage());}});Ui.primary(open);p.addView(open);return;}
 LinearLayout courseCard=a.card(p);courseCard.addView(a.text(course.has("courseId")?"当前课程 "+course.optString("courseId"):"选择课程",16));LinearLayout tools=a.row();a.equal(tools,a.button("读取当前页",()->fromPage()));a.equal(tools,a.button("粘贴链接",()->{android.widget.EditText input=a.input("课程或活动HTTPS链接","");new AlertDialog.Builder(a).setTitle("读取课程").setView(input).setNegativeButton("取消",null).setPositiveButton("读取",(d,n)->{try{useCourse(SignLogic.course(input.getText().toString().trim()));}catch(Exception e){a.message(e.getMessage());}}).show();}));a.equal(tools,a.button("刷新活动",()->refresh()));courseCard.addView(tools);
 try{JSONArray rows=new JSONArray(a.store.setting(a.aid,"signinActivities","[]"));if(rows.length()==0)p.addView(a.text("暂无活动。读取课程后刷新。",14));for(int i=0;i<rows.length();i++){JSONObject e=rows.getJSONObject(i);if(course.has("courseId")&&!course.optString("courseId").equals(e.optString("courseId")))continue;LinearLayout c=a.card(p);JSONObject r=record(e.optString("id"));String phase=r.optString("state");c.addView(a.text(e.optString("title"),17));c.addView(a.text((e.optString("kind").equals("location")?"位置签到":e.optString("kind").equals("normal")?"普通签到":"人工签到")+" · "+(e.optBoolean("ongoing")?"活动进行中":"活动已结束"),12));if(!phase.isEmpty())c.addView(Ui.badge(a,label(phase)));if(!r.optString("message").isEmpty())c.addView(a.text(r.optString("message"),12));LinearLayout actions=a.row();if(e.optBoolean("ongoing")&&!phase.equals("completed"))a.equal(actions,a.button("打开签到页",()->open(e)));if(!phase.isEmpty())a.equal(actions,a.button("核对平台结果",()->{current=e;recheck();}));c.addView(actions);}}catch(Exception e){a.message("本机活动记录读取失败，请刷新");}}
 void useCourse(JSONObject c)throws Exception{SignLogic.digits(c.optString("courseId"));SignLogic.digits(c.optString("classId"));course=c;a.store.setSetting(a.aid,"signinCourse",c.toString());refresh();}
 void fromPage(){if(a.web==null||!Store.trusted(a.web.getUrl(),"chaoxing")){a.message("请先在学习页打开课程");return;}String js="JSON.stringify((()=>{const p=new URL(location.href).searchParams;const field=(ids)=>{for(const id of ids){let e=document.getElementById(id);if(e&&e.value)return e.value;}return '';};return {courseId:p.get('courseId')||p.get('courseid')||field(['courseId','courseid']),classId:p.get('classId')||p.get('clazzid')||p.get('jclassId')||field(['classId','clazzId','clazzid'])};})())";a.web.evaluateJavascript(js,v->{try{useCourse(MainActivity.decode(v));}catch(Exception e){a.message("当前页没有课程信息，请打开具体课程或粘贴活动页链接");}});}
 String get(String url,String cookie)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new java.net.URL(url).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(25000);if(cookie!=null)c.setRequestProperty("Cookie",cookie);try{if(c.getResponseCode()!=200)throw new Exception("平台读取失败，请重新登录当前账号");try(InputStream in=c.getInputStream()){return MainActivity.read(in,4*1024*1024);}}finally{c.disconnect();}}
 void refresh(){try{if(a.slotIndex()<0)throw new Exception("请先打开当前账号空间");String cid=SignLogic.digits(course.optString("courseId")),clazz=SignLogic.digits(course.optString("classId"));String cookie=CookieManager.getInstance().getCookie("https://mobilelearn.chaoxing.com");if(cookie==null||cookie.isEmpty())throw new Exception("请先在当前账号的学习页登录平台");a.message("正在读取当前课程签到活动…");a.worker.submit(()->{try{String url="https://mobilelearn.chaoxing.com/v2/apis/active/student/activelist?fid=0&courseId="+cid+"&classId="+clazz+"&showNotStartedActive=0";List<JSONObject> parsed=SignLogic.activities(new JSONObject(get(url,cookie)),course);JSONArray rows=new JSONArray();for(JSONObject item:parsed)rows.put(item);a.store.setSetting(a.aid,"signinActivities",rows.toString());a.runOnUiThread(()->{if(a.page.equals("签到"))a.show();a.message("已读取 "+rows.length()+" 个签到活动，仅当前账号可见");});}catch(Exception e){a.runOnUiThread(()->{a.message(e.getMessage());if(e.getMessage()!=null&&e.getMessage().contains("平台限制访问")&&a.store.setting(a.aid,"security","true").equals("true"))new AlertDialog.Builder(a).setTitle("平台安全提示").setMessage(e.getMessage()).setPositiveButton("知道了",null).show();});}});}catch(Exception e){a.message(e.getMessage());}}
 void open(JSONObject entry){try{cancelLocation();point=null;current=entry;a.store.setSetting(a.aid,"signinCurrent",entry.toString());String url=SignLogic.url(entry.getString("id"),entry.getString("courseId"),entry.getString("classId"));a.section="签到";a.page="学习";a.render();a.navigate(url);a.message("已打开平台签到页；位置签到请先获取本机位置");}catch(Exception e){a.message(e.getMessage());}}
 void controls(LinearLayout parent){LinearLayout r=a.row();a.equal(r,a.button("获取本机位置",()->locate()));a.equal(r,a.button("确认签到",()->confirm()));a.equal(r,a.button("核对结果",()->recheck()));parent.addView(r);}
 boolean pageMatches(){return a.web!=null&&current!=null&&SignLogic.matches(a.web.getUrl(),current);}
 void locate(){if(!pageMatches()){a.message("请从签到中心打开需要处理的活动");return;}if(a.checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=0){a.requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},45);return;}cancelLocation();manager=(LocationManager)a.getSystemService(Context.LOCATION_SERVICE);Location best=null;for(String provider:manager.getProviders(true))try{Location l=manager.getLastKnownLocation(provider);if(SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos())&&LocationModeManager.accepts(a,a.aid,l)&&(best==null||l.getAccuracy()<best.getAccuracy()))best=l;}catch(SecurityException ignored){}if(best!=null){reviewLocation(best);return;}a.message("正在获取本机位置，请确认系统定位已开启…");listener=new LocationListener(){public void onLocationChanged(Location l){if(SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos())&&LocationModeManager.accepts(a,a.aid,l)){cancelLocation();reviewLocation(l);}}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};boolean requested=false;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(manager.isProviderEnabled(provider)){manager.requestLocationUpdates(provider,1000,0,listener,Looper.getMainLooper());requested=true;}}catch(Exception ignored){}if(!requested){cancelLocation();a.message("本机定位未开启。请打开系统定位后重试；模拟器需先提供测试坐标。");return;}timeout=()->{cancelLocation();a.message("没有获取到新鲜有效的位置，未提交签到。请检查系统定位或模拟器定位设置。");};a.timer.postDelayed(timeout,20000);}
 void permission(int[] grant){if(grant.length>0&&grant[0]==0)locate();else a.message("定位权限未授予，未获取或提交位置。可在系统权限设置中开启精确位置。");}
 void cancelLocation(){if(timeout!=null)a.timer.removeCallbacks(timeout);timeout=null;if(manager!=null&&listener!=null)try{manager.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
 void reviewLocation(Location l){if(!pageMatches())return;try{a.store.setSetting(a.aid,"location.lastSystem",LocationModeManager.fix(l).toString());}catch(Exception ignored){}double[] b=SignLogic.bd09(l.getLongitude(),l.getLatitude());String message=String.format(Locale.ROOT,"本机位置（WGS84）\n纬度 %.6f，经度 %.6f\n精度约 %.0f 米\n来源 %s，系统模拟标记 %s\n\n平台位置格式：BD09\n纬度 %.6f，经度 %.6f\n\n提供位置不代表签到成功，仍需确认签到。",l.getLatitude(),l.getLongitude(),l.getAccuracy(),l.getProvider(),LocationModeManager.isMock(l)?"是":"否",b[1],b[0]);new AlertDialog.Builder(a).setTitle("确认提供本机位置").setMessage(message).setNegativeButton("取消",null).setPositiveButton("提供给当前签到页",(d,n)->provide(l)).show();}
 void provide(Location l){try{if(!pageMatches()||(!SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos())||!LocationModeManager.accepts(a,a.aid,l)))throw new Exception("页面或位置已变化，请重新获取位置");point=l;double[] b=SignLogic.bd09(l.getLongitude(),l.getLatitude());JSONObject p=new JSONObject().put("result",1).put("latitude",b[1]).put("longitude",b[0]).put("address",String.format(Locale.ROOT,"经度%.6f，纬度%.6f（本机定位）",b[0],b[1])).put("locType",-200).put("accuracy",l.getAccuracy()).put("coordinateType","bd09ll").put("source","Android LocationManager").put("isMock",LocationModeManager.isMock(l));String code="(function(expected,position){const u=new URL(location.href);if(u.searchParams.get('activePrimaryId')!==expected.id||u.searchParams.get('courseId')!==expected.courseId||u.searchParams.get('classId')!==expected.classId)return JSON.stringify({ok:false});if(!window.jsBridge||!jsBridge.trigger)return JSON.stringify({ok:false});if(!jsBridge.callbackDict?.CLIENT_USER_LOCATION?.length&&typeof _jsBridgeReady==='function')_jsBridgeReady();if(String(window.openCheckFaceFlag||'0')==='1')return JSON.stringify({ok:false,face:true});try{jsBridge.trigger('CLIENT_USER_LOCATION',position);}catch(mapError){}return JSON.stringify({ok:document.querySelector('#paramAddress')?.value&&Math.abs(Number(document.querySelector('#latitude')?.value)-position.latitude)<1e-7});})("+current.toString()+","+p.toString()+")";a.web.evaluateJavascript(code,v->{try{JSONObject r=MainActivity.decode(v);if(r.optBoolean("ok")){state("located","位置已提供给平台，等待你确认签到");}else{point=null;state("verification",r.optBoolean("face")?"平台要求人脸验证，请使用平台支持的客户端完成":"当前平台页面尚未接受位置，未提交签到");}}catch(Exception e){a.message("位置回填未确认，未提交签到");}});}catch(Exception e){a.message(e.getMessage());}}
 void confirm(){try{if(!pageMatches())throw new Exception("请从签到中心打开活动");JSONObject r=record(current.optString("id"));if(r.optString("state").equals("completed"))throw new Exception("平台已确认本活动签到成功");if(r.optBoolean("claimed"))throw new Exception("已有提交记录，请先核对结果，不会重复发起");if(current.optString("kind").equals("manual"))throw new Exception("此签到方式需要在平台中人工处理");if(current.optString("kind").equals("location")&&(!SignLogic.fresh(point,SystemClock.elapsedRealtimeNanos())||!LocationModeManager.accepts(a,a.aid,point)||!r.optString("state").equals("located")))throw new Exception("请先获取并确认提供本机位置");new AlertDialog.Builder(a).setTitle("确认签到").setMessage("向平台提交本次签到？位置签到会提交刚刚确认的本机位置。若平台要求额外验证，需要手动完成。").setNegativeButton("取消",null).setPositiveButton("确认提交",(d,n)->submit()).show();}catch(Exception e){a.message(e.getMessage());}}
 void submit(){try{if(!pageMatches())throw new Exception("页面已变化，未提交");if(current.optString("kind").equals("location")&&(!SignLogic.fresh(point,SystemClock.elapsedRealtimeNanos())||!LocationModeManager.accepts(a,a.aid,point)))throw new Exception("位置已过期，请重新获取；未提交签到");JSONObject r=record(current.getString("id"));if(r.optBoolean("claimed"))return;r.put("claimed",true);a.store.setSetting(a.aid,"signin:"+current.getString("id"),r.toString());state("submitting","已请求平台签到，等待真实回执；请勿重复点击");submittedAt=SystemClock.elapsedRealtime();observe(()->{String js="(function(e){let u=new URL(location.href);if(u.searchParams.get('activePrimaryId')!==e.id||u.searchParams.get('courseId')!==e.courseId||u.searchParams.get('classId')!==e.classId)return JSON.stringify({ok:false});if(String(window.openCheckFaceFlag||'0')==='1')return JSON.stringify({ok:false,face:true});if(typeof sign!=='function')return JSON.stringify({ok:false});sign();return JSON.stringify({ok:true});})("+current+")";a.web.evaluateJavascript(js,v->{try{JSONObject ack=MainActivity.decode(v);if(!ack.optBoolean("ok"))state("verification",ack.optBoolean("face")?"平台要求人脸验证，未代替验证":"没有识别到可执行的签到入口，请核对平台");}catch(Exception e){state("uncertain","尚未确认平台结果，请点击核对结果");}});});}catch(Exception e){a.message(e.getMessage());}}
 void observe(Runnable after){if(!pageMatches())return;if(pollBusy){if(after!=null&&a.alive)a.timer.postDelayed(()->observe(after),100);return;}final String observingId=current.optString("id");pollBusy=true;try{String script=a.asset("signin-observe.js")+"("+current+")";a.web.evaluateJavascript(script,v->{pollBusy=false;if(!observingId.equals(current.optString("id")))return;try{JSONObject result=MainActivity.decode(v);if(result.optBoolean("ok")){String verdict=SignLogic.verdict(result.optString("reply"),result.optString("body"));if(!verdict.equals("pending")){String msg=verdict.equals("completed")?"平台已确认签到成功":verdict.equals("verification")?"平台要求人工验证，请在原页面处理":verdict.equals("rejected")?"平台未接受本次位置，请核对范围；平台可能不接受Mock定位，软件不会隐藏标记":"平台结果待核对，请勿重复提交";state(verdict,msg);if(verdict.equals("rejected")){JSONObject r=record(current.optString("id"));r.put("claimed",false);a.store.setSetting(a.aid,"signin:"+current.optString("id"),r.toString());}if(verdict.equals("verification")&&a.store.setting(a.aid,"security","true").equals("true")&&!reminded.equals(current.optString("id"))){reminded=current.optString("id");new AlertDialog.Builder(a).setTitle("平台安全验证提醒").setMessage(msg).setPositiveButton("知道了",null).show();}}if(after!=null&&!verdict.equals("completed"))after.run();}else a.message("签到页面未就绪，请稍候或重新打开活动");}catch(Exception e){a.message("平台回执暂不可读，请核对结果");}});}catch(Exception e){pollBusy=false;}}
 void tick(){if(submittedAt>0&&SystemClock.elapsedRealtime()-submittedAt>45000&&record(current.optString("id")).optString("state").equals("submitting")){submittedAt=0;state("uncertain","等待平台回执超时，请核对结果；不会重复提交");}if(pageMatches())observe(null);}
 void recheck(){try{if(current==null||!current.has("id"))throw new Exception("请先选择签到活动");final String checkingId=current.getString("id");String url=SignLogic.url(checkingId,current.getString("courseId"),current.getString("classId"));String cookie=CookieManager.getInstance().getCookie("https://mobilelearn.chaoxing.com");a.worker.submit(()->{try{String html=get(url,cookie).replaceAll("(?is)<script\\b[^>]*>.*?</script>","").replaceAll("(?is)<style\\b[^>]*>.*?</style>","");String body=Html.fromHtml(html,Html.FROM_HTML_MODE_LEGACY).toString();String v=SignLogic.verdict("",body);a.runOnUiThread(()->{if(!checkingId.equals(current.optString("id")))return;if(v.equals("completed"))state(v,"只读核对：平台已确认签到成功");else if(v.equals("ended"))state(v,"平台显示签到已结束");else a.message("已只读核对，尚未确认成功；没有重新提交签到");});}catch(Exception e){a.runOnUiThread(()->{a.message(e.getMessage());if(e.getMessage()!=null&&e.getMessage().contains("平台限制访问")&&a.store.setting(a.aid,"security","true").equals("true"))new AlertDialog.Builder(a).setTitle("平台安全提示").setMessage(e.getMessage()).setPositiveButton("知道了",null).show();});}});}catch(Exception e){a.message(e.getMessage());}}
}
